const Checkout: React.FC = () => {
  const { cart, cartTotal, clearCart } = useCart();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
    city: ''
  });

  if (cart.length === 0) {
    return (
      <div className="h-screen flex flex-col items-center justify-center gap-4">
        <h2 className="text-2xl font-bold">Your cart is empty</h2>
        <button onClick={() => navigate('/shop')} className="text-purple-600 hover:underline">Go Shopping</button>
      </div>
    );
  }

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleWhatsAppCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // 1. Create Order in Backend (Mock)
    await storeService.createOrder({
      items: cart,
      total: cartTotal,
      customerName: formData.name,
      customerPhone: formData.phone,
      status: 'pending'
    });

    // 2. Format WhatsApp Message
    const itemsList = cart.map(item => `• ${item.title} (x${item.qty}) - ${CURRENCY_SYMBOL} ${item.price_retail * item.qty}`).join('%0a');

