  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
    city: ''
  });

  if (cart.length === 0) {
    return (
      <div className="h-screen flex flex-col items-center justify-center gap-4">
