      `*Items:*%0a${itemsList}%0a%0a` +
      `*Total:* ${CURRENCY_SYMBOL} ${cartTotal.toLocaleString()}`;

    // 3. Clear Cart & Redirect
    clearCart();
    setLoading(false);
    window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${message}`, '_blank');
