              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-3 rounded-xl bg-white/50 dark:bg-white/10 dark:text-white dark:border-gray-600 border border-white/60 focus:outline-none focus:ring-2 focus:ring-purple-500 shadow-sm transition-all"
            />
          </div>

          {/* Categories */}
          <div className="glass-card p-6 rounded-2xl">
            <h3 className="font-bold text-gray-800 dark:text-gray-100 mb-4 flex items-center gap-2">
              <Filter size={18} /> Categories
            </h3>
            <div className="space-y-2">
              <button 
                onClick={() => setSelectedCategory('All')}
                className={`w-full text-left px-3 py-2 rounded-lg transition-colors ${selectedCategory === 'All' ? 'bg-purple-100 dark:bg-purple-900/50 text-purple-700 dark:text-purple-300 font-medium' : 'text-gray-600 dark:text-gray-300 hover:bg-white/50 dark:hover:bg-white/10'}`}
              >
                All Categories
              </button>
              {CATEGORIES.map(cat => (
                <button 
                  key={cat}
                  onClick={() => setSelectedCategory(cat)}
                  className={`w-full text-left px-3 py-2 rounded-lg transition-colors ${selectedCategory === cat ? 'bg-purple-100 dark:bg-purple-900/50 text-purple-700 dark:text-purple-300 font-medium' : 'text-gray-600 dark:text-gray-300 hover:bg-white/50 dark:hover:bg-white/10'}`}
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* Price Filter */}
          <div className="glass-card p-6 rounded-2xl">
             <h3 className="font-bold text-gray-800 dark:text-gray-100 mb-4">Max Price</h3>
             <input 
               type="range" 
               min="0" 
               max="500000" 
               step="5000"
               value={priceRange}
               onChange={(e) => setPriceRange(Number(e.target.value))}
               className="w-full h-2 bg-gray-200 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-purple-600"
             />
             <div className="flex justify-between mt-2 text-sm text-gray-600 dark:text-gray-400">
               <span>0</span>
               <span>{priceRange.toLocaleString()} LKR</span>
             </div>
          </div>
        </aside>

        {/* Product Grid */}
        <div className="flex-1">
          <div className="mb-6 flex items-center justify-between">
            <h1 className="text-2xl font-bold text-gray-800 dark:text-gray-100">
              {selectedCategory} <span className="text-gray-400 font-normal text-lg">({filteredProducts.length} items)</span>
            </h1>

            {/* Active Filters Tags */}
            {(selectedCategory !== 'All' || searchQuery) && (
              <button 
                onClick={() => { setSelectedCategory('All'); setSearchQuery(''); }}
                className="text-sm text-red-500 hover:text-red-700 dark:hover:text-red-400 flex items-center gap-1"
              >
                Clear Filters <X size={14} />
              </button>
            )}
          </div>

          {loading ? (
             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
               {[1,2,3,4,5,6].map(n => (
                 <div key={n} className="h-80 glass-card rounded-2xl animate-pulse"></div>
               ))}
             </div>
          ) : filteredProducts.length === 0 ? (
            <div className="glass-panel rounded-2xl p-12 text-center text-gray-500 dark:text-gray-400">
              <p className="text-xl">No products found.</p>
              <p className="mt-2 text-sm">Try adjusting your search or filters.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredProducts.map(product => (
                <ProductCard key={product.id} product={product} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Shop;

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Minus, Plus, ShoppingBag, ArrowLeft, Share2 } from 'lucide-react';
import { storeService } from '../services/storeService.ts';
import { Product } from '../types.ts';
import { useCart } from '../context/CartContext.tsx';
import { CURRENCY_SYMBOL } from '../constants.ts';

const ProductDetails: React.FC = () => {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const { addToCart } = useCart();

  const [product, setProduct] = useState<Product | null>(null);
  const [loading, setLoading] = useState(true);
  const [qty, setQty] = useState(1);
  const [activeImage, setActiveImage] = useState(0);

  useEffect(() => {
    if (slug) {
      storeService.getProductBySlug(slug).then(data => {
        setProduct(data || null);
        setLoading(false);
      });
    }
  }, [slug]);

  if (loading) return <div className="h-screen flex items-center justify-center"><div className="w-10 h-10 border-4 border-purple-600 border-t-transparent rounded-full animate-spin"></div></div>;

  if (!product) return (
    <div className="h-screen flex flex-col items-center justify-center gap-4 text-gray-800 dark:text-gray-100">
      <h2 className="text-2xl font-bold">Product not found</h2>
      <button onClick={() => navigate('/shop')} className="text-purple-600 dark:text-purple-400 hover:underline">Back to Shop</button>
    </div>
  );

  const discountPrice = product.discount 
    ? product.price_retail * (1 - product.discount / 100) 
    : product.price_retail;

  return (
    <div className="pt-32 pb-20 px-6 max-w-7xl mx-auto min-h-screen">
      <button 
        onClick={() => navigate(-1)} 
        className="flex items-center gap-2 text-gray-500 hover:text-gray-900 dark:text-gray-400 dark:hover:text-white mb-8 transition-colors"
      >
        <ArrowLeft size={20} /> Back
      </button>

      <div className="grid md:grid-cols-2 gap-12">
        {/* Gallery */}
        <div className="space-y-4">
          <div className="aspect-square rounded-3xl overflow-hidden glass-card p-2 bg-white/50 dark:bg-white/5">
            <img 
              src={product.images[activeImage]} 
              alt={product.title} 
              className="w-full h-full object-cover rounded-2xl shadow-sm"
            />
          </div>
          <div className="flex gap-4 overflow-x-auto pb-2">
            {product.images.map((img, idx) => (
              <button 
                key={idx}
                onClick={() => setActiveImage(idx)}
                className={`w-20 h-20 rounded-xl overflow-hidden border-2 transition-all flex-shrink-0 ${activeImage === idx ? 'border-purple-600 ring-2 ring-purple-600/20' : 'border-transparent opacity-70 hover:opacity-100'}`}
              >
                <img src={img} alt="" className="w-full h-full object-cover" />
              </button>
            ))}
          </div>
        </div>

        {/* Info */}
        <div className="glass-panel p-8 rounded-3xl h-fit animate-fade-in-up">
          <div className="flex justify-between items-start mb-4">
            <span className="bg-purple-100 dark:bg-purple-900/50 text-purple-700 dark:text-purple-300 px-3 py-1 rounded-full text-sm font-bold uppercase tracking-wide">
              {product.category}
            </span>
            <button className="p-2 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full text-gray-500 dark:text-gray-400 transition-colors">
              <Share2 size={20} />
            </button>
          </div>

          <h1 className="text-3xl md:text-4xl font-bold text-gray-900 dark:text-white mb-4">{product.title}</h1>

          <div className="flex items-end gap-4 mb-6">
            <span className="text-4xl font-bold text-purple-600 dark:text-purple-400">
              {CURRENCY_SYMBOL} {discountPrice.toLocaleString()}
            </span>
            {product.discount && (
              <span className="text-xl text-gray-400 line-through mb-1">
                {CURRENCY_SYMBOL} {product.price_retail.toLocaleString()}
              </span>
            )}
          </div>

          <p className="text-gray-600 dark:text-gray-300 leading-relaxed mb-8 text-lg">
            {product.description}
          </p>

          <div className="space-y-6 pt-6 border-t border-gray-200/50 dark:border-gray-700/50">
            {/* Quantity */}
            <div className="flex items-center gap-6">
              <span className="font-medium text-gray-700 dark:text-gray-300">Quantity</span>
              <div className="flex items-center gap-4 bg-white/60 dark:bg-white/10 rounded-xl px-4 py-2 border border-white dark:border-gray-600">
                <button 
                  onClick={() => setQty(Math.max(1, qty - 1))}
                  className="p-1 hover:text-purple-600 dark:hover:text-purple-400 dark:text-gray-200 transition-colors"
                >
                  <Minus size={18} />
                </button>
                <span className="font-bold text-lg w-8 text-center text-gray-900 dark:text-white">{qty}</span>
                <button 
                  onClick={() => setQty(qty + 1)}
                  className="p-1 hover:text-purple-600 dark:hover:text-purple-400 dark:text-gray-200 transition-colors"
                >
                  <Plus size={18} />
                </button>
              </div>
              <span className="text-sm text-gray-500 dark:text-gray-400">
                {product.stock} pieces available
              </span>
            </div>

            {/* Actions */}
            <div className="flex gap-4">
              <button 
                onClick={() => addToCart(product, qty)}
                className="flex-1 bg-gray-900 dark:bg-white dark:text-gray-900 text-white py-4 rounded-xl font-bold text-lg shadow-xl hover:bg-gray-800 dark:hover:bg-gray-200 hover:shadow-2xl hover:-translate-y-1 transition-all flex items-center justify-center gap-2"
              >
                <ShoppingBag size={20} /> Add to Cart
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetails;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Send, MapPin } from 'lucide-react';
import { useCart } from '../context/CartContext.tsx';
import { CURRENCY_SYMBOL, WHATSAPP_NUMBER } from '../constants.ts';
import { storeService } from '../services/storeService.ts';

const Checkout: React.FC = () => {
  const { cart, cartTotal, clearCart } = useCart();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    address: '',
    city: ''
  });

  if (cart.length === 0) {
    return (
      <div className="h-screen flex flex-col items-center justify-center gap-4 text-gray-800 dark:text-gray-100">
        <h2 className="text-2xl font-bold">Your cart is empty</h2>
        <button onClick={() => navigate('/shop')} className="text-purple-600 dark:text-purple-400 hover:underline">Go Shopping</button>
      </div>
    );
  }

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleWhatsAppCheckout = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // 1. Create Order in Backend (Mock)
    await storeService.createOrder({
      items: cart,
      total: cartTotal,
      customerName: formData.name,
      customerPhone: formData.phone,
      status: 'pending'
    });

    // 2. Format WhatsApp Message
    const itemsList = cart.map(item => `• ${item.title} (x${item.qty}) - ${CURRENCY_SYMBOL} ${item.price_retail * item.qty}`).join('%0a');

    const message = `*New Order Request* 🛍️%0a%0a` +
      `*Customer:* ${formData.name}%0a` +
      `*Phone:* ${formData.phone}%0a` +
      `*Address:* ${formData.address}, ${formData.city}%0a%0a` +
      `*Items:*%0a${itemsList}%0a%0a` +
      `*Total:* ${CURRENCY_SYMBOL} ${cartTotal.toLocaleString()}`;

    // 3. Clear Cart & Redirect
    clearCart();
    setLoading(false);
    window.open(`https://wa.me/${WHATSAPP_NUMBER}?text=${message}`, '_blank');
    navigate('/'); // Or to a success page
  };

  return (
    <div className="pt-32 pb-20 px-6 max-w-7xl mx-auto min-h-screen">
      <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-10 text-center">Checkout</h1>

      <div className="grid md:grid-cols-2 gap-12">
        {/* Order Summary */}
        <div className="glass-card p-8 rounded-3xl h-fit order-2 md:order-1">
          <h2 className="text-xl font-bold text-gray-800 dark:text-gray-100 mb-6">Order Summary</h2>
          <div className="space-y-4 max-h-96 overflow-y-auto pr-2 custom-scrollbar">
            {cart.map(item => (
              <div key={item.id} className="flex gap-4 py-4 border-b border-gray-200/30 dark:border-gray-700/30 last:border-0">
                <img src={item.images[0]} alt={item.title} className="w-16 h-16 rounded-lg object-cover" />
                <div className="flex-1">
                  <h4 className="font-semibold text-gray-800 dark:text-gray-200 text-sm">{item.title}</h4>
                  <div className="flex justify-between mt-1 text-sm">
                    <span className="text-gray-500 dark:text-gray-400">Qty: {item.qty}</span>
                    <span className="font-medium text-gray-900 dark:text-gray-100">{CURRENCY_SYMBOL} {(item.price_retail * item.qty).toLocaleString()}</span>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-6 pt-6 border-t border-gray-200/50 dark:border-gray-700/50 space-y-2">
            <div className="flex justify-between text-gray-600 dark:text-gray-300">
              <span>Subtotal</span>
              <span>{CURRENCY_SYMBOL} {cartTotal.toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-gray-600 dark:text-gray-300">
              <span>Shipping</span>
              <span className="text-green-600 dark:text-green-400 font-medium">Calculated via WhatsApp</span>
            </div>
            <div className="flex justify-between text-2xl font-bold text-gray-900 dark:text-white pt-4">
              <span>Total</span>
              <span>{CURRENCY_SYMBOL} {cartTotal.toLocaleString()}</span>
            </div>
          </div>
        </div>

        {/* Form */}
        <div className="glass-panel p-8 rounded-3xl order-1 md:order-2">
          <h2 className="text-xl font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
            <MapPin className="text-purple-600 dark:text-purple-400" /> Delivery Details
          </h2>

          <form onSubmit={handleWhatsAppCheckout} className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Full Name</label>
              <input 
                required 
                name="name"
                value={formData.name}
                onChange={handleInputChange}
                type="text" 
                className="w-full px-4 py-3 rounded-xl bg-white/50 dark:bg-white/10 dark:text-white dark:border-gray-600 border border-gray-200 focus:ring-2 focus:ring-purple-500 outline-none transition-all"
                placeholder="John Doe"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Phone Number</label>
              <input 
                required 
                name="phone"
                value={formData.phone}
                onChange={handleInputChange}
                type="tel" 
                className="w-full px-4 py-3 rounded-xl bg-white/50 dark:bg-white/10 dark:text-white dark:border-gray-600 border border-gray-200 focus:ring-2 focus:ring-purple-500 outline-none transition-all"
                placeholder="077 123 4567"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
               <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">City</label>
                <input 
                  required 
                  name="city"
                  value={formData.city}
                  onChange={handleInputChange}
                  type="text" 
                  className="w-full px-4 py-3 rounded-xl bg-white/50 dark:bg-white/10 dark:text-white dark:border-gray-600 border border-gray-200 focus:ring-2 focus:ring-purple-500 outline-none transition-all"
                  placeholder="Colombo"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Postal Code</label>
                <input 
                  type="text" 
                  className="w-full px-4 py-3 rounded-xl bg-white/50 dark:bg-white/10 dark:text-white dark:border-gray-600 border border-gray-200 focus:ring-2 focus:ring-purple-500 outline-none transition-all"
                  placeholder="10000"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Address</label>
              <textarea 
                required 
                name="address"
                value={formData.address}
                onChange={handleInputChange}
                rows={3}
                className="w-full px-4 py-3 rounded-xl bg-white/50 dark:bg-white/10 dark:text-white dark:border-gray-600 border border-gray-200 focus:ring-2 focus:ring-purple-500 outline-none transition-all"
                placeholder="Street address, apartment, etc."
              />
            </div>

            <button 
              type="submit" 
              disabled={loading}
              className="w-full py-4 bg-[#25D366] text-white rounded-xl font-bold text-lg shadow-lg hover:shadow-green-500/40 hover:-translate-y-1 transition-all flex items-center justify-center gap-3 disabled:opacity-70"
            >
              {loading ? 'Processing...' : (
                <>
                  <Send size={20} /> Order via WhatsApp
                </>
              )}
            </button>
            <p className="text-center text-xs text-gray-500 dark:text-gray-400 mt-4">
              By clicking above, you will be redirected to WhatsApp to confirm your order with our agent.
            </p>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Checkout;

