                        'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400'
                      }`}>
                        {order.status}
                      </span>
                    </div>
                  </div>

                  <div className="space-y-3">
                    {order.items.map((item, idx) => (
                      <div key={idx} className="flex items-center gap-4">
                         <div className="w-12 h-12 rounded-lg bg-white/50 dark:bg-white/5 overflow-hidden flex-shrink-0">
                           <img src={item.images[0]} alt="" className="w-full h-full object-cover" />
                         </div>
                         <div className="flex-1">
                           <p className="text-sm font-medium text-gray-800 dark:text-gray-200 line-clamp-1">{item.title}</p>
                           <p className="text-xs text-gray-500 dark:text-gray-400">Qty: {item.qty} × {CURRENCY_SYMBOL} {item.price_retail.toLocaleString()}</p>
                         </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

