import { Product, Order } from '../types.ts';
import { MOCK_PRODUCTS } from '../constants.ts';

// Simulating API delay
const delay = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

class StoreService {
  private products: Product[] = [];
  private orders: Order[] = [];

  constructor() {
    this.loadFromStorage();
  }

  private loadFromStorage() {
    if (typeof window !== 'undefined') {
      const savedProducts = localStorage.getItem('wr_products');
      const savedOrders = localStorage.getItem('wr_orders');

      if (savedProducts) {
        this.products = JSON.parse(savedProducts);
      } else {
        this.products = [...MOCK_PRODUCTS];
        this.saveProducts();
      }

      if (savedOrders) {
        this.orders = JSON.parse(savedOrders);
      }
    }
  }

  private saveProducts() {
    localStorage.setItem('wr_products', JSON.stringify(this.products));
  }

  private saveOrders() {
    localStorage.setItem('wr_orders', JSON.stringify(this.orders));
  }

  async getProducts(): Promise<Product[]> {
    await delay(500);
    return this.products;
  }

  async getProductBySlug(slug: string): Promise<Product | undefined> {
    await delay(300);
    return this.products.find(p => p.slug === slug);
  }

  async createOrder(order: Omit<Order, 'id' | 'createdAt'>): Promise<Order> {
    await delay(800);
    const newOrder: Order = {
      ...order,
      id: Math.random().toString(36).substring(7).toUpperCase(),
      createdAt: new Date().toISOString(),
    };
    this.orders.unshift(newOrder); // Add to beginning
    this.saveOrders();
    return newOrder;
  }

  async getUserOrders(email: string): Promise<Order[]> {
    await delay(500);
    return this.orders.filter(o => o.userEmail === email);
  }

  async updateOrderStatus(orderId: string, status: Order['status']): Promise<void> {
    await delay(400);
    this.orders = this.orders.map(o => o.id === orderId ? { ...o, status } : o);
    this.saveOrders();
  }

  // Admin functions
  async addProduct(product: Omit<Product, 'id' | 'createdAt'>): Promise<Product> {
    await delay(600);
    const newProduct: Product = {
      ...product,
      id: Math.random().toString(36).substring(7),
      createdAt: new Date().toISOString()
    };
    this.products.unshift(newProduct);
    this.saveProducts();
    return newProduct;
  }

  async updateProduct(product: Product): Promise<void> {
    await delay(500);
    this.products = this.products.map(p => p.id === product.id ? product : p);
    this.saveProducts();
  }

  async deleteProduct(id: string): Promise<void> {
    await delay(400);
    this.products = this.products.filter(p => p.id !== id);
    this.saveProducts();
  }

  async getOrders(): Promise<Order[]> {
    await delay(500);
    return this.orders;
  }
}

export const storeService = new StoreService();

