  createUserWithEmailAndPassword, 
  signOut, 
  updateProfile,
  User as FirebaseUser
} from 'firebase/auth';
import { doc, setDoc, getDoc } from 'firebase/firestore';
import { auth, db } from '../firebase.ts';
import { User } from '../types.ts';

export const authService = {
  async login(email: string, password: string): Promise<User> {
    try {
      // 1. Authenticate with Firebase Auth
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      // 2. Try to fetch extra profile data from Firestore
      let name = fbUser.displayName || 'User';

      try {
        const userDoc = await getDoc(doc(db, 'users', fbUser.uid));
        if (userDoc.exists()) {
          const userData = userDoc.data();
          name = userData.name || name;
        }
      } catch (firestoreError) {
        console.warn("Could not fetch user profile from Firestore:", firestoreError);
      }

      // FORCE ADMIN: Return user with admin role regardless of database value
      return {
        uid: fbUser.uid,
        name,
        email: fbUser.email!,
        role: 'admin' 
      };
    } catch (error) {
      console.error("Firebase Login Error:", error);
      throw error;
    }
  },

  async register(name: string, email: string, password: string): Promise<User> {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      await updateProfile(fbUser, { displayName: name });

      // FORCE ADMIN: Assign admin role to all new registrations
      const role = 'admin';

      const newUser: User = {
        uid: fbUser.uid,
        name,
        email,
        role
      };

      // Save user details to Firestore for persistence
      try {
        await setDoc(doc(db, 'users', fbUser.uid), newUser);
      } catch (e) {
        console.warn("Could not save user profile to Firestore (likely permission issue)", e);
      }

      return newUser;
    } catch (error) {
      console.error("Firebase Register Error:", error);
      throw error;
    }
  },

  async logout(): Promise<void> {
    try {
      await signOut(auth);
    } catch (e) {
      console.error("Logout error", e);
    }
  }
};

