} from 'firebase/auth';
import { doc, setDoc, getDoc } from 'firebase/firestore';
import { auth, db } from '../firebase.ts';
import { User } from '../types.ts';

const googleProvider = new GoogleAuthProvider();

export const authService = {
  async login(email: string, password: string): Promise<User> {
    try {
      // 1. Authenticate with Firebase Auth
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      // 2. Try to fetch extra profile data from Firestore
      let role = 'customer';
      let name = fbUser.displayName || 'User';

      try {
        const userDoc = await getDoc(doc(db, 'users', fbUser.uid));
        if (userDoc.exists()) {
          const userData = userDoc.data();
          role = userData.role || 'customer';
          name = userData.name || name;
        }
      } catch (firestoreError) {
        console.warn("Could not fetch user profile from Firestore:", firestoreError);
      }

      // Hardcoded admin check
      if (email === 'admin@wrsmile.com') {
        role = 'admin';
      }

      return {
        uid: fbUser.uid,
        name,
        email: fbUser.email!,
        role: role as 'admin' | 'customer'
      };
    } catch (error) {
      console.error("Firebase Login Error:", error);
      throw error;
    }
  },

  async register(name: string, email: string, password: string): Promise<User> {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      await updateProfile(fbUser, { displayName: name });

      // Determine role: Only specific email is admin
      const role = email === 'admin@wrsmile.com' ? 'admin' : 'customer';

      const newUser: User = {
        uid: fbUser.uid,
        name,
        email,
        role
      };

      // Save user details to Firestore for persistence
      try {
        await setDoc(doc(db, 'users', fbUser.uid), newUser);
      } catch (e) {
        console.warn("Could not save user profile to Firestore (likely permission issue)", e);
      }

      return newUser;
    } catch (error) {
      console.error("Firebase Register Error:", error);
      throw error;
    }
  },

  async loginWithGoogle(): Promise<User> {
    try {
      const result = await signInWithPopup(auth, googleProvider);
      const fbUser = result.user;

      const userDocRef = doc(db, 'users', fbUser.uid);
      let role = 'customer';
      let name = fbUser.displayName || 'User';

      try {
        const userDoc = await getDoc(userDocRef);

        if (userDoc.exists()) {
          // Existing user
          const userData = userDoc.data();
          role = userData.role || 'customer';
          name = userData.name || name;
        } else {
          // New Google user - Create Firestore Doc
          if (fbUser.email === 'admin@wrsmile.com') {
            role = 'admin';
          }

          const newUser: User = {
            uid: fbUser.uid,
            name,
            email: fbUser.email!,
            role: role as 'admin' | 'customer'
          };

          await setDoc(userDocRef, newUser);
        }
      } catch (e) {
        console.warn("Firestore access error during Google Login", e);
      }

      // Enforce admin check again just in case
      if (fbUser.email === 'admin@wrsmile.com') role = 'admin';

      return {
        uid: fbUser.uid,
        name,
        email: fbUser.email!,
        role: role as 'admin' | 'customer'
      };

    } catch (error) {
      console.error("Google Login Error:", error);
      throw error;
    }
  },

  async logout(): Promise<void> {
    try {
      await signOut(auth);
    } catch (e) {
      console.error("Logout error", e);
    }
  }
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { User } from '../types.ts';
import { authService } from '../services/authService.ts';

interface AuthContextType {
  user: User | null;
  loading: boolean;
  login: (email: string, pass: string) => Promise<void>;
  loginWithGoogle: () => Promise<void>;
  register: (name: string, email: string, pass: string) => Promise<void>;
  logout: () => Promise<void>;
  isAdmin: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(false);

  // Check localStorage on mount to persist session
  useEffect(() => {
    const savedUser = localStorage.getItem('wr_user');
    if (savedUser) {
      setUser(JSON.parse(savedUser));
    }
  }, []);

  const login = async (email: string, pass: string) => {
    setLoading(true);
    try {
      const user = await authService.login(email, pass);
      setUser(user);
      localStorage.setItem('wr_user', JSON.stringify(user));
    } finally {
      setLoading(false);
    }
  };

  const loginWithGoogle = async () => {
    setLoading(true);
    try {
      const user = await authService.loginWithGoogle();
      setUser(user);
      localStorage.setItem('wr_user', JSON.stringify(user));
    } finally {
      setLoading(false);
    }
  };

  const register = async (name: string, email: string, pass: string) => {
    setLoading(true);
    try {
      const user = await authService.register(name, email, pass);
      setUser(user);
      localStorage.setItem('wr_user', JSON.stringify(user));
    } finally {
      setLoading(false);
    }
  };

  const logout = async () => {
    await authService.logout();
    setUser(null);
    localStorage.removeItem('wr_user');
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      loading, 
      login,
      loginWithGoogle, 
      register, 
      logout,
      isAdmin: user?.role === 'admin'
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth must be used within AuthProvider');
  return context;
};

