import { 
  collection, 
  getDocs, 
  doc, 
  addDoc, 
  updateDoc, 
  deleteDoc, 
  query, 
  where, 
  orderBy,
  writeBatch
} from 'firebase/firestore';
import { db } from '../firebase';
import { Product, Order } from '../types';
import { MOCK_PRODUCTS } from '../constants';

class StoreService {

  // Products
  async getProducts(): Promise<Product[]> {
    const querySnapshot = await getDocs(collection(db, 'products'));
    const products: Product[] = [];
    querySnapshot.forEach((doc) => {
      products.push({ id: doc.id, ...doc.data() } as Product);
    });

    // SEED DATA: If DB is empty, upload mock products automatically
    if (products.length === 0) {
      return this.seedProducts();
    }

    return products;
  }

  async getProductBySlug(slug: string): Promise<Product | undefined> {
    const q = query(collection(db, 'products'), where("slug", "==", slug));
    const querySnapshot = await getDocs(q);

    if (!querySnapshot.empty) {
      const doc = querySnapshot.docs[0];
      return { id: doc.id, ...doc.data() } as Product;
    }
    return undefined;
  }

  async addProduct(product: Omit<Product, 'id' | 'createdAt'>): Promise<Product> {
    const docRef = await addDoc(collection(db, 'products'), {
      ...product,
      createdAt: new Date().toISOString()
    });
    return { id: docRef.id, ...product, createdAt: new Date().toISOString() } as Product;
  }

  async updateProduct(product: Product): Promise<void> {
    const productRef = doc(db, 'products', product.id);
    const { id, ...data } = product; // Exclude ID from data payload
    await updateDoc(productRef, data);
  }

  async deleteProduct(id: string): Promise<void> {
    await deleteDoc(doc(db, 'products', id));
  }

  // Orders
  async createOrder(order: Omit<Order, 'id' | 'createdAt'>): Promise<Order> {
    const newOrderData = {
      ...order,
      createdAt: new Date().toISOString()
    };
    const docRef = await addDoc(collection(db, 'orders'), newOrderData);
    return { id: docRef.id, ...newOrderData } as Order;
  }

  async getOrders(): Promise<Order[]> {
    // Get all orders ordered by date
    const q = query(collection(db, 'orders'), orderBy('createdAt', 'desc'));
    const querySnapshot = await getDocs(q);
    const orders: Order[] = [];
    querySnapshot.forEach((doc) => {
      orders.push({ id: doc.id, ...doc.data() } as Order);
    });
    return orders;
  }

  async getUserOrders(email: string): Promise<Order[]> {
    const q = query(collection(db, 'orders'), where("userEmail", "==", email));
    const querySnapshot = await getDocs(q);
    const orders: Order[] = [];
    querySnapshot.forEach((doc) => {
      orders.push({ id: doc.id, ...doc.data() } as Order);
    });
    // Sort in memory since Firestore requires composite index for 'where' + 'orderBy'
    return orders.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }

  async updateOrderStatus(orderId: string, status: Order['status']): Promise<void> {
    const orderRef = doc(db, 'orders', orderId);
    await updateDoc(orderRef, { status });
  }

  // Helper to seed initial data
  private async seedProducts(): Promise<Product[]> {
    const batch = writeBatch(db);
    const productsCollection = collection(db, 'products');
    const createdProducts: Product[] = [];

    MOCK_PRODUCTS.forEach(product => {
      const docRef = doc(productsCollection); // Create new doc ref with auto ID
      const { id, ...data } = product; // Remove the mock ID 1, 2, 3...
      const pData = { ...data, createdAt: new Date().toISOString() };
      batch.set(docRef, pData);
      createdProducts.push({ id: docRef.id, ...pData } as Product);
    });

    await batch.commit();
    return createdProducts;
  }
}

export const storeService = new StoreService();

import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword, 
  signOut, 
  updateProfile,
  signInWithPopup,
  GoogleAuthProvider,
  User as FirebaseUser
} from 'firebase/auth';
import { doc, setDoc, getDoc } from 'firebase/firestore';
import { auth, db } from '../firebase';
import { User } from '../types';

const googleProvider = new GoogleAuthProvider();

export const authService = {
  async login(email: string, password: string): Promise<User> {
    try {
      // 1. Authenticate with Firebase Auth
      const userCredential = await signInWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      // 2. Try to fetch extra profile data from Firestore
      let role = 'customer';
      let name = fbUser.displayName || 'User';

      try {
        const userDoc = await getDoc(doc(db, 'users', fbUser.uid));
        if (userDoc.exists()) {
          const userData = userDoc.data();
          role = userData.role || 'customer';
          name = userData.name || name;
        }
      } catch (firestoreError) {
        console.warn("Could not fetch user profile from Firestore:", firestoreError);
      }

      // Hardcoded admin check
      if (email === 'admin@wrsmile.com') {
        role = 'admin';
      }

      return {
        uid: fbUser.uid,
        name,
        email: fbUser.email!,
        role: role as 'admin' | 'customer'
      };
    } catch (error) {
      console.error("Firebase Login Error:", error);
      throw error;
    }
  },

  async register(name: string, email: string, password: string): Promise<User> {
    try {
      const userCredential = await createUserWithEmailAndPassword(auth, email, password);
      const fbUser = userCredential.user;

      await updateProfile(fbUser, { displayName: name });

      // Determine role: Only specific email is admin
      const role = email === 'admin@wrsmile.com' ? 'admin' : 'customer';

      const newUser: User = {
        uid: fbUser.uid,
        name,
        email,
        role
      };

      // Save user details to Firestore for persistence
      try {
        await setDoc(doc(db, 'users', fbUser.uid), newUser);
      } catch (e) {
        console.warn("Could not save user profile to Firestore (likely permission issue)", e);
      }

      return newUser;
    } catch (error) {
      console.error("Firebase Register Error:", error);
      throw error;
    }
  },

  async loginWithGoogle(): Promise<User> {
    try {
      const result = await signInWithPopup(auth, googleProvider);
      const fbUser = result.user;

      const userDocRef = doc(db, 'users', fbUser.uid);
      let role = 'customer';
      let name = fbUser.displayName || 'User';

      try {
        const userDoc = await getDoc(userDocRef);

        if (userDoc.exists()) {
          // Existing user
          const userData = userDoc.data();
          role = userData.role || 'customer';
          name = userData.name || name;
        } else {
          // New Google user - Create Firestore Doc
          if (fbUser.email === 'admin@wrsmile.com') {
            role = 'admin';
          }

          const newUser: User = {
            uid: fbUser.uid,
            name,
            email: fbUser.email!,
            role: role as 'admin' | 'customer'
          };

          await setDoc(userDocRef, newUser);
        }
      } catch (e) {
        console.warn("Firestore access error during Google Login", e);
      }

      // Enforce admin check again just in case
      if (fbUser.email === 'admin@wrsmile.com') role = 'admin';

      return {
        uid: fbUser.uid,
        name,
        email: fbUser.email!,
        role: role as 'admin' | 'customer'
      };

    } catch (error) {
      console.error("Google Login Error:", error);
      throw error;
    }
  },

  async loginAsDemoUser(): Promise<User> {
    // Simulate network delay for realistic feel
    await new Promise(resolve => setTimeout(resolve, 800));

    return {
      uid: 'demo-user-' + Math.random().toString(36).substring(2, 9),
      name: 'Demo User',
      email: 'demo@example.com',
      role: 'customer'
    };
  },

  async logout(): Promise<void> {
    try {
      await signOut(auth);
    } catch (e) {
      console.error("Logout error", e);
    }
  }
};

