import React from 'react';
import { Link } from 'react-router-dom';
import { Star } from 'lucide-react';
import { Product } from '../types';
import { CURRENCY_SYMBOL } from '../constants';
import { useCart } from '../context/CartContext';

interface ProductCardProps {
  product: Product;
}

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const { addToCart } = useCart();

  const discountPrice = product.discount 
    ? product.price_retail * (1 - product.discount / 100) 
    : null;

  const handleAddToCart = (e: React.MouseEvent) => {
    e.preventDefault(); 
    addToCart(product, 1);
  };

  return (
    <Link 
      to={`/product/${product.slug}`}
      className="block bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-sm overflow-hidden hover:shadow-lg transition-shadow h-full flex flex-col"
    >
      {/* Image Area */}
      <div className="relative p-6 bg-white flex items-center justify-center h-52">
         {product.discount && (
            <span className="absolute top-2 right-2 text-xs font-bold text-red-600 bg-red-50 px-2 py-1 rounded">
               -{product.discount}%
            </span>
         )}
         <img 
            src={product.images[0]} 
            alt={product.title} 
            className="max-h-full max-w-full object-contain"
         />
      </div>

      {/* Content Area */}
      <div className="p-4 flex flex-col flex-1">
         {/* Title */}
         <h3 className="text-gray-900 dark:text-gray-100 font-medium leading-tight line-clamp-2 hover:text-orange-600 dark:hover:text-orange-400 mb-1">
            {product.title}
         </h3>

         {/* Ratings (Mock) */}
         <div className="flex items-center gap-1 mb-2">
            <div className="flex text-yellow-500">
               {[...Array(4)].map((_, i) => <Star key={i} size={14} fill="currentColor" />)}
               <Star size={14} className="text-gray-300" />
            </div>
            <span className="text-xs text-blue-600 hover:underline cursor-pointer">456</span>
         </div>

         {/* Price */}
         <div className="mt-auto">
            {discountPrice ? (
               <div className="flex items-baseline gap-2">
                  <span className="text-xs align-top relative top-[-4px]">{CURRENCY_SYMBOL}</span>
                  <span className="text-2xl font-medium text-gray-900 dark:text-white">
                     {discountPrice.toLocaleString()}
                  </span>
                  <span className="text-xs text-gray-500 line-through">
                     {CURRENCY_SYMBOL}{product.price_retail.toLocaleString()}
                  </span>
               </div>
            ) : (
               <div className="flex items-baseline">
                  <span className="text-xs align-top relative top-[-4px]">{CURRENCY_SYMBOL}</span>
                  <span className="text-2xl font-medium text-gray-900 dark:text-white">
                     {product.price_retail.toLocaleString()}
                  </span>
               </div>
            )}
            <div className="text-xs text-gray-500 mb-3">
               Delivery by <span className="font-bold text-gray-700 dark:text-gray-300">Tomorrow</span>
            </div>

            <button 
               onClick={handleAddToCart}
               className="w-full btn-primary py-1.5 text-sm shadow-sm"
            >
               Add to Cart
            </button>
         </div>
      </div>
    </Link>
  );
};

export default ProductCard;

