import React from 'react';
import { Link } from 'react-router-dom';
import { ShoppingBag } from 'lucide-react';
import { Product } from '../types';
import { CURRENCY_SYMBOL } from '../constants';
import { useCart } from '../context/CartContext';

interface ProductCardProps {
  product: Product;
}

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const { addToCart } = useCart();

  const discountPrice = product.discount 
    ? product.price_retail * (1 - product.discount / 100) 
    : null;

  const handleAddToCart = (e: React.MouseEvent) => {
    e.preventDefault(); 
    addToCart(product, 1);
  };

  return (
    <Link 
      to={`/product/${product.slug}`}
      className="group glass-card rounded-2xl overflow-hidden flex flex-col h-full relative"
    >
      {product.discount && (
        <div className="absolute top-3 right-3 z-10 bg-red-500 text-white text-xs font-bold px-2 py-1 rounded-full shadow-lg">
          -{product.discount}%
        </div>
      )}

      <div className="relative aspect-square overflow-hidden p-6 bg-white/50 dark:bg-white/5 group-hover:bg-white/60 dark:group-hover:bg-white/10 transition-colors">
        <img 
          src={product.images[0]} 
          alt={product.title} 
          className="w-full h-full object-contain transform group-hover:scale-110 transition-transform duration-500"
        />
      </div>

      <div className="p-5 flex flex-col flex-grow">
        <div className="flex-grow">
          <p className="text-xs font-semibold text-purple-600 dark:text-purple-400 mb-1 uppercase tracking-wider">
            {product.category}
          </p>
          <h3 className="font-bold text-gray-800 dark:text-white text-lg leading-tight mb-2 line-clamp-2 group-hover:text-purple-600 dark:group-hover:text-purple-400 transition-colors">
            {product.title}
          </h3>
        </div>

        <div className="flex items-center justify-between mt-4">
          <div>
            {discountPrice ? (
              <div className="flex flex-col">
                <span className="text-sm text-gray-400 line-through">
                  {CURRENCY_SYMBOL} {product.price_retail.toLocaleString()}
                </span>
                <span className="text-xl font-bold text-gray-900 dark:text-white">
                  {CURRENCY_SYMBOL} {discountPrice.toLocaleString()}
                </span>
              </div>
            ) : (
              <span className="text-xl font-bold text-gray-900 dark:text-white">
                {CURRENCY_SYMBOL} {product.price_retail.toLocaleString()}
              </span>
            )}
          </div>

          <button 
            onClick={handleAddToCart}
            className="p-3 rounded-xl bg-gray-900 dark:bg-white text-white dark:text-gray-900 shadow-lg hover:scale-110 active:scale-95 transition-all"
            aria-label="Add to cart"
          >
            <ShoppingBag size={20} />
          </button>
        </div>
      </div>
    </Link>
  );
};

export default ProductCard;

