import React, { useEffect, useState } from 'react';
import { Package, Plus, Trash, Search, X, Save, Upload, Edit, ChevronDown, ChevronUp, ShoppingBag } from 'lucide-react';
import { storeService } from '../services/storeService';
import { Product, Order } from '../types';
import { CURRENCY_SYMBOL, CATEGORIES } from '../constants';
import { useAuth } from '../context/AuthContext';
import { useNavigate } from 'react-router-dom';

const Admin: React.FC = () => {
  const { isAdmin, loading: authLoading } = useAuth();
  const navigate = useNavigate();

  const [products, setProducts] = useState<Product[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [activeTab, setActiveTab] = useState<'products' | 'orders'>('products');
  const [expandedOrder, setExpandedOrder] = useState<string | null>(null);

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [productForm, setProductForm] = useState<Partial<Product>>({
    title: '',
    category: 'Electronics',
    price_retail: 0,
    stock: 0,
    description: '',
    images: [''],
    featured: false
  });

  useEffect(() => {
    // Redirect if not admin
    if (!authLoading && !isAdmin) {
      navigate('/login');
    }
  }, [isAdmin, authLoading, navigate]);

  useEffect(() => {
    if (isAdmin) {
      loadData();
    }
  }, [isAdmin]);

  const loadData = () => {
    storeService.getProducts().then(setProducts);
    storeService.getOrders().then(setOrders);
  };

  const openAddModal = () => {
    setEditingProduct(null);
    setProductForm({
      title: '',
      category: 'Electronics',
      price_retail: 0,
      stock: 0,
      description: '',
      images: [''],
      featured: false
    });
    setIsModalOpen(true);
  };

  const openEditModal = (product: Product) => {
    setEditingProduct(product);
    setProductForm({ ...product });
    setIsModalOpen(true);
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;

    if (type === 'checkbox') {
      const checked = (e.target as HTMLInputElement).checked;
      setProductForm(prev => ({ ...prev, [name]: checked }));
    } else if (type === 'number') {
      setProductForm(prev => ({ ...prev, [name]: Number(value) }));
    } else {
      setProductForm(prev => ({ ...prev, [name]: value }));
    }
  };

  const handleImageChange = (value: string) => {
    setProductForm(prev => ({ ...prev, images: [value] }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!productForm.title || !productForm.price_retail) return;

    if (editingProduct) {
      // Update existing
      await storeService.updateProduct({
        ...editingProduct,
        ...productForm as any
      });
    } else {
      // Create new
      const slug = productForm.title.toLowerCase().replace(/ /g, '-').replace(/[^\w-]+/g, '');
      await storeService.addProduct({
        ...productForm as any,
        slug,
        discount: 0
      });
    }

    setIsModalOpen(false);
    loadData();
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this product?')) {
      await storeService.deleteProduct(id);
      loadData();
    }
  };

  const handleStatusChange = async (orderId: string, newStatus: Order['status']) => {
    await storeService.updateOrderStatus(orderId, newStatus);
    loadData();
  };

  const toggleOrderExpand = (id: string) => {
    setExpandedOrder(expandedOrder === id ? null : id);
  };

  if (!isAdmin) return null;

  return (
    <div className="py-12 px-6 max-w-7xl mx-auto min-h-screen">
      <div className="mb-10">
        <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-6">Admin Dashboard</h1>

        {/* Professional Border Tabs */}
        <div className="border-b border-gray-200 dark:border-gray-700 flex gap-8">
          <button 
            onClick={() => setActiveTab('products')}
            className={`pb-4 px-2 font-medium text-sm transition-all relative ${
              activeTab === 'products' 
                ? 'text-indigo-600 dark:text-indigo-400' 
                : 'text-gray-500 hover:text-gray-800 dark:hover:text-gray-200'
            }`}
          >
            <span className="flex items-center gap-2">
               <Package size={18} /> Products
            </span>
            {activeTab === 'products' && (
