                  <div>
                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-2 tracking-wide">Category</label>
                    <div className="relative">
                       <select 
                        name="category"
                        value={productForm.category}
                        onChange={handleInputChange}
                        className="w-full px-4 py-2.5 rounded-lg bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-700 focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-white appearance-none transition-all"
                      >
                        {CATEGORIES.map(cat => (
                          <option key={cat} value={cat} className="text-black">{cat}</option>
                        ))}
                      </select>
                      <ChevronDown className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none" size={16} />
                    </div>
                  </div>
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-2 tracking-wide">Price ({CURRENCY_SYMBOL})</label>
                    <input 
                      name="price_retail"
                      type="number"
                      value={productForm.price_retail}
                      onChange={handleInputChange}
                      className="w-full px-4 py-2.5 rounded-lg bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-700 focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-white transition-all"
                      required
                    />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-2 tracking-wide">Stock Qty</label>
                    <input 
                      name="stock"
                      type="number"
                      value={productForm.stock}
                      onChange={handleInputChange}
                      className="w-full px-4 py-2.5 rounded-lg bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-700 focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-white transition-all"
                      required
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-2 tracking-wide">Image URL</label>
                  <input 
                    name="images"
                    value={productForm.images?.[0] || ''}
                    onChange={(e) => handleImageChange(e.target.value)}
                    className="w-full px-4 py-2.5 rounded-lg bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-700 focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-white transition-all"
                    placeholder="https://..."
                  />
                </div>

                <div>
                  <label className="block text-xs font-bold text-gray-500 dark:text-gray-400 uppercase mb-2 tracking-wide">Description</label>
                  <textarea 
                    name="description"
                    value={productForm.description}
                    onChange={handleInputChange}
                    rows={4}
                    className="w-full px-4 py-2.5 rounded-lg bg-gray-50 dark:bg-black/20 border border-gray-200 dark:border-gray-700 focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-white transition-all resize-none"
                  />
                </div>

                <div className="flex items-center gap-3 p-4 bg-gray-50 dark:bg-black/20 rounded-xl">
                  <input 
                    type="checkbox" 
                    name="featured"
                    checked={productForm.featured}
                    onChange={handleInputChange}
                    id="featured"
                    className="w-5 h-5 rounded text-indigo-600 focus:ring-indigo-500 border-gray-300"
                  />
                  <label htmlFor="featured" className="text-gray-900 dark:text-white font-medium select-none cursor-pointer">Mark as Featured Product</label>
                </div>

                <button 
                  type="submit"
                  className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold shadow-lg shadow-indigo-500/20 hover:shadow-indigo-500/40 hover:-translate-y-0.5 transition-all flex items-center justify-center gap-2"
                >
                  <Save size={20} /> {editingProduct ? 'Update Product' : 'Save Product'}
                </button>
              </form>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

