  const [activeTab, setActiveTab] = useState<Tab>('orders');

  useEffect(() => {
    if (!authLoading && !user) {
      navigate('/login');
    }
  }, [user, authLoading, navigate]);

  useEffect(() => {
    if (user?.email) {
      storeService.getUserOrders(user.email).then(data => {
        setOrders(data);
        setLoadingOrders(false);
      });
    }
  }, [user]);

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  if (!user) return null;

