                <span className="absolute top-0 right-0 w-5 h-5 bg-indigo-600 text-white text-[10px] font-bold flex items-center justify-center rounded-full shadow-lg border-2 border-white dark:border-gray-900 group-hover:scale-110 transition-transform">
                  {cartCount}
                </span>
              )}
            </button>

            <div className="h-6 w-px bg-gray-200 dark:bg-gray-700 hidden sm:block"></div>

            {user ? (
              <Link to="/profile" className="hidden sm:block">
                <div className="w-10 h-10 rounded-full bg-gradient-to-r from-indigo-500 to-fuchsia-500 p-[2px] cursor-pointer hover:shadow-lg transition-all">
                  <div className="w-full h-full bg-white dark:bg-gray-900 rounded-full flex items-center justify-center text-sm font-bold text-gray-700 dark:text-white">
                    {user.name.charAt(0).toUpperCase()}
                  </div>
                </div>
              </Link>
            ) : (
              <Link 
                to="/login"
                className="hidden sm:flex items-center gap-2 px-6 py-2.5 rounded-full bg-gray-900 dark:bg-white text-white dark:text-gray-900 font-bold text-sm shadow-lg hover:shadow-xl hover:-translate-y-0.5 transition-all"
              >
                <span>Login</span>
              </Link>
            )}

            <button 
              className="md:hidden p-2.5 text-gray-700 dark:text-gray-200"
              onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            >
              {isMobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </nav>

      {/* Mobile Menu */}
      {isMobileMenuOpen && (
        <div className="md:hidden absolute top-24 left-4 right-4 glass-panel rounded-3xl animate-fade-in-down shadow-2xl p-4 z-40 border border-white/20">
          <div className="flex flex-col gap-2">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`p-4 rounded-2xl font-semibold transition-colors flex items-center justify-between ${
                  location.pathname === link.path
                    ? 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-300'
                    : 'text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-white/5'
                }`}
              >
                {link.name}
              </Link>
            ))}
            {isAdmin && (
              <Link
                to="/admin"
                className="p-4 rounded-2xl font-semibold text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-white/5"
              >
                Admin Dashboard
              </Link>
            )}
            <hr className="border-gray-100 dark:border-gray-700/50 my-2" />
            {user ? (
              <>
                <Link to="/profile" className="p-4 rounded-2xl font-semibold text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-white/5 flex items-center gap-3">
                  <div className="w-8 h-8 rounded-full bg-indigo-100 dark:bg-indigo-900/50 flex items-center justify-center text-indigo-600">
                    <UserIcon size={16} />
                  </div>
                  My Profile
                </Link>
                <button 
                  onClick={handleLogout}
                  className="w-full p-4 rounded-2xl font-semibold text-red-500 hover:bg-red-50 dark:hover:bg-red-900/10 flex items-center gap-3 text-left"
                >
                  <div className="w-8 h-8 rounded-full bg-red-100 dark:bg-red-900/50 flex items-center justify-center text-red-500">
                    <LogOut size={16} />
                  </div>
                  Sign Out
                </button>
              </>
            ) : (
              <Link
                to="/login"
                className="p-4 rounded-2xl font-bold bg-gray-900 dark:bg-white text-white dark:text-gray-900 text-center shadow-lg mt-2"
              >
                Sign In / Register
              </Link>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Navbar;

import React from 'react';
import { Link } from 'react-router-dom';
import { ShoppingBag, Plus } from 'lucide-react';
import { Product } from '../types';
import { CURRENCY_SYMBOL } from '../constants';
import { useCart } from '../context/CartContext';

interface ProductCardProps {
  product: Product;
}

const ProductCard: React.FC<ProductCardProps> = ({ product }) => {
  const { addToCart } = useCart();

  const discountPrice = product.discount 
    ? product.price_retail * (1 - product.discount / 100) 
    : null;

  const handleAddToCart = (e: React.MouseEvent) => {
    e.preventDefault(); 
    addToCart(product, 1);
  };

  return (
    <Link 
      to={`/product/${product.slug}`}
      className="group glass-card rounded-[2rem] overflow-hidden flex flex-col h-full relative"
    >
      {/* Discount Badge */}
      {product.discount && (
        <div className="absolute top-4 right-4 z-10 bg-white/90 dark:bg-black/80 backdrop-blur-md text-gray-900 dark:text-white text-xs font-bold px-3 py-1.5 rounded-full shadow-sm border border-black/5 dark:border-white/10">
          -{product.discount}%
        </div>
      )}

      {/* Image Area */}
      <div className="relative aspect-square overflow-hidden p-8 bg-gradient-to-br from-white/40 to-white/10 dark:from-white/5 dark:to-transparent group-hover:from-white/50 dark:group-hover:from-white/10 transition-colors">
        <img 
          src={product.images[0]} 
          alt={product.title} 
          className="w-full h-full object-contain transform group-hover:scale-110 transition-transform duration-700 ease-in-out drop-shadow-xl"
        />

        {/* Quick Add Button (Visible on Hover) */}
        <button 
          onClick={handleAddToCart}
          className="absolute bottom-4 right-4 w-12 h-12 rounded-full bg-gray-900 dark:bg-white text-white dark:text-gray-900 flex items-center justify-center shadow-2xl translate-y-20 opacity-0 group-hover:translate-y-0 group-hover:opacity-100 transition-all duration-300 hover:scale-110 z-20"
          aria-label="Add to cart"
        >
          <Plus size={24} />
        </button>
      </div>

      {/* Content Area */}
      <div className="p-6 flex flex-col flex-grow">
        <div className="flex-grow">
          <p className="text-[10px] font-bold text-indigo-500 dark:text-indigo-400 mb-2 uppercase tracking-widest">
            {product.category}
          </p>
          <h3 className="font-bold text-gray-800 dark:text-white text-lg leading-snug mb-2 group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors">
            {product.title}
          </h3>
        </div>

        <div className="flex items-end gap-2 mt-4">
          {discountPrice ? (
            <>
              <span className="text-xl font-bold text-gray-900 dark:text-white">
                {CURRENCY_SYMBOL} {discountPrice.toLocaleString()}
              </span>
              <span className="text-sm text-gray-400 line-through mb-1">
                {product.price_retail.toLocaleString()}
              </span>
            </>
          ) : (
            <span className="text-xl font-bold text-gray-900 dark:text-white">
              {CURRENCY_SYMBOL} {product.price_retail.toLocaleString()}
            </span>
          )}
        </div>
      </div>
    </Link>
  );
};

export default ProductCard;

